package org.springframework.samples.petclinic.util;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

/**
 * SHA-256 hashing rendered as hexadecimal. Kept separate from any one caller so the
 * digest algorithm is defined once and reused wherever a stable hex fingerprint of a
 * string is needed (e.g. the hash component of an owner's customer code).
 */
public final class Sha256 {

    private Sha256() {
    }

    /**
     * The first {@code length} upper-case hexadecimal characters of the SHA-256 digest of
     * the UTF-8 bytes of {@code value}.
     *
     * @param value  the string to hash
     * @param length the number of leading hex characters to return
     * @return {@code length} upper-case hex characters
     */
    public static String upperHexPrefix(String value, int length) {
        byte[] digest = digest(value);
        StringBuilder hex = new StringBuilder(length);
        for (int i = 0; hex.length() < length; i++) {
            hex.append(String.format(Locale.ROOT, "%02X", digest[i]));
        }
        return hex.substring(0, length);
    }

    private static byte[] digest(String value) {
        try {
            return MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
        }
    }
}
=== DupHouseholdException ===
package org.springframework.samples.petclinic.rest.escalation;

/**
 * Thrown when a create-owner request would repeat an existing owner in a household (same
 * last name and postcode, so the same derived {@code householdId}, and the same telephone)
 * without opting in to sharing that household. A different person in the same household is a
 * legitimate additional member and is not rejected here. Handled by
 * {@link DuplicateHouseholdExceptionHandler}, which responds 409.
 */
public class DuplicateHouseholdException extends Exception {

    private final String householdId;

    public DuplicateHouseholdException(String householdId) {
        super("An owner already exists in this household: " + householdId);
        this.householdId = householdId;
    }

    public String getHouseholdId() {
        return this.householdId;
    }
}
=== Handler ===
package org.springframework.samples.petclinic.rest.escalation;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;

public class DuplicateHouseholdExceptionHandler {

    public void handle(@Parameter DuplicateHouseholdException ex,
            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.CONFLICT,
                "An owner already exists in this household; set 'sharesHousehold' to add another");
        response.send(ResponseEntity.status(HttpStatus.CONFLICT).body(detail));
    }
}
