/**
 * Flags a soft duplicate. A new owner that reaches this step is not blocked by the
 * household duplicate check ({@link EnsureUniqueHousehold}) — it has no existing household
 * member, it opted in with {@code sharesHousehold}, or it shares a household but differs in
 * telephone. A declared member ({@code sharesHousehold}) is a genuine household member, not a
 * suspected duplicate, so it is never flagged here. Any other owner that shares an existing
 * owner's household (same last name and postcode, hence the same {@code householdId}, see
 * {@link Households}) but differs in telephone is created anyway and marked as a possible
 * duplicate of that owner. Runs before {@link SaveOwner}
 * persists the flags; when several match, the earliest (lowest id) is recorded. An owner
 * with no postcode has no household and can never be a possible duplicate.
 */
public class AssignOwnerPossibleDuplicate {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
        if (owner.getHouseholdId() == null || Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        Households.membersOf(ownerRepository, owner.getLastName(), owner.getPostcode()).stream()
                .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
                .min(Comparator.comparingInt(Owner::getId))
                .ifPresent(match -> {
                    owner.setPossibleDuplicate(true);
                    owner.setPossibleDuplicateOf(match.getId());
                });
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the new owner's deterministic {@code householdId} (see {@link Households}),
 * derived from its last name and postcode, so every owner that shares a last name and
 * postcode resolves to the same stable value automatically — no coordination and no
 * opt-in required. An owner with no postcode gets no household id. Runs after
 * {@link BuildOwner} (so the entity, its name and postcode exist) and before the household
 * duplicate check ({@link EnsureUniqueHousehold}) and {@link SaveOwner}, both of which key
 * off this value.
 */
public class AssignHouseholdId {

    public void service(@Val Owner owner) {
        owner.setHouseholdId(Households.idFor(owner.getLastName(), owner.getPostcode()));
    }
}

